// ==== Changes list hydration ====
// Populate the changes page's #changes-list from site/log.json (landed ticks,
// newest first) so the page's "full list, newest first" promise is kept and
// the copy/download/share buttons have real rows to export. Purely additive
// and guarded: pages without #changes-list never fetch, and a failed fetch
// leaves any static fallback items intact.
function hydrateChangesList() {
  const list = document.getElementById('changes-list');
  if (!list) return;
  fetch('log.json')
    .then((r) => {
      if (!r.ok) throw new Error('log.json unavailable');
      return r.json();
    })
    .then((entries) => {
      if (!Array.isArray(entries)) return;
      list.textContent = '';
      entries.forEach((entry) => {
        if (!entry || entry.state !== 'landed') return;
        const when = entry.run_at || entry.date || '';
        const what = String(entry.changed_paths || '').split(' ').filter(Boolean).join(', ');
        const li = document.createElement('li');
        li.textContent = when + ' — ' + what;
        list.appendChild(li);
      });
    })
    .catch(() => {
      // log.json unavailable; keep any static fallback items
    });
}
if (document.readyState === 'loading') {
  document.addEventListener('DOMContentLoaded', hydrateChangesList);
} else {
  hydrateChangesList();
}
